// launch-factory: 동의 조립. 가입 때의 약관·개인정보·만 14세 동의 기록은 인증 항목이 이미 남긴다(consent_records, 추가만 하는 이력 — 고칠 수 없다).
// 이 파일은 그 뒤의 동의를 다룬다: 채널별 마케팅 수신 동의(NotifyPort)와 본인 동의 이력 읽기. 로그인한 본인만 — 사용자 id 는 세션에서 읽는다.
import { notifyAdapter, type MarketingChangeEvent } from "@launch-factory/consent"
import { consentHistory, type NoticeSource } from "@launch-factory/db"
import { authPort } from "@/lib/launch/auth"
import { DEFAULT_LOCALE } from "@/lib/launch/config"
import { database } from "@/lib/launch/db"
import { sendMarketingNotice } from "@/lib/launch/notices"

/** 지금 로그인한 본인의 id. 없으면 null. 대리 로그인 세션의 주인은 대상 사용자다 — 관리자가 대신 동의·거부를 바꾸지 못하도록 본인이 아닌 것으로 본다 */
export async function currentUserId(): Promise<string | null> {
  const s = await (await authPort()).session()
  return s.ok && s.data && !s.data.impersonatedBy ? s.data.userId : null
}

/**
 * 처리 결과 통지(정보통신망법 제50조제7항 · 시행령 제62조의2 — 의사를 표시한 날부터 14일 안에 전송자 명칭·의사 표시 사실과 날짜·처리 결과, 대장 D201).
 * 동의·거부·철회를 표시할 때마다 그 사람의 메일로 바로 보낸다(같은 값을 다시 표시해도 보낸다). 보내기가 실패하면 발신함에 남고 Cron(/api/cron/notices)이 다시 보낸다(대장 D210) —
 * 설정 저장은 되돌리지 않는다. 대체 주소(카카오 이메일 없는 계정)로는 보낼 수 없어 건너뛴다: 화면 응답이 통지를 대신하지 못하니 그런 계정에 마케팅을 켜기 전에 다른 통지 수단을 정해야 한다.
 * 보내는 일은 lib/launch/notices.ts 한 곳이다(가입·설정·수신거부 링크가 같은 길).
 */
export async function sendResultNotice(event: MarketingChangeEvent, source: NoticeSource = "settings"): Promise<void> {
  await sendMarketingNotice({ userId: event.userId, changes: event.changes, at: event.at }, source)
}

/**
 * 마케팅 수신 동의 포트. 채널(이메일·문자·카카오·푸시)마다 기본 거부이고, 바꿀 때마다 이력이 남는다(정보통신망법 제50조).
 * 바꿀 때마다 처리 결과 통지 메일이 나간다(제50조제7항).
 */
export async function notifyPort() {
  return notifyAdapter({ db: await database(), userId: currentUserId, locale: DEFAULT_LOCALE, onChange: sendResultNotice })
}

/** 본인의 동의 이력(오래된 것부터). 증빙에 쓰는 칸만 돌려준다 */
export async function myConsentHistory() {
  const userId = await currentUserId()
  if (!userId) return null
  const rows = await consentHistory(await database(), userId)
  return rows.map((r) => ({ kind: r.kind, granted: r.granted, version: r.version, source: r.source, locale: r.locale, at: r.createdAt.toISOString() }))
}

"use server"
// launch-factory: 동의 서버 액션. 로그인한 사용자 자신의 동의에만 작용한다(세션에서 읽는다 — 사용자 id 를 입력으로 받지 않는다).
// 입력 모양 검사는 포트가 한다: 채널 이름(email·sms·kakao·push)과 boolean 만 받고, 그 밖의 칸은 fieldErrors 로 돌려준다.
// 수신 동의 변경은 사람의 확인 입력(`confirmed: true`) 없이는 실행하지 않는다(LFAX M03) — 없으면 DB·알림 메일을 건드리지 않고 confirmation_required.
import { confirmedNotifyActions, type Confirmed } from "@launch-factory/consent"
import { signInRequiredResult } from "@launch-factory/security/action"
import { DEFAULT_LOCALE } from "@/lib/launch/config"
import { myConsentHistory, notifyPort } from "@/lib/launch/consents"

export async function getMarketingConsents() {
  return (await notifyPort()).consents()
}

/** 예: setMarketingConsents({ email: true, confirmed: true }) — 준 채널만 바뀌고 바뀐 것마다 이력이 한 줄 남는다 */
export async function setMarketingConsents(input: Parameters<Awaited<ReturnType<typeof notifyPort>>["setConsents"]>[0]) {
  // 타입은 블록 props 모양(확인 칸 선택) — 확인 칸 검사는 런타임(confirmedNotifyActions)이 한다
  return confirmedNotifyActions(await notifyPort(), { locale: DEFAULT_LOCALE }).setConsents(input as Confirmed<typeof input>)
}

/** 본인 동의 이력(가입 동의 포함) */
export async function getMyConsentHistory() {
  const history = await myConsentHistory()
  return history ? { ok: true as const, data: history } : signInRequiredResult(DEFAULT_LOCALE)
}

// launch-factory: DB 연결. mock 은 메모리 PGlite(키 없이 켜진다), live 는 DATABASE_URL(Supabase 풀러 6543 — prepared statement 끔은 패키지가 한다).
// mock 의 마이그레이션은 이 앱에 설치된 db/migrations 를 쓴다(번들 안에서는 패키지 폴더를 찾을 수 없다).
import { join } from "node:path"
import { db, type Database } from "@launch-factory/db"
import { env, required } from "@/lib/launch/env"

let cached: Promise<Database> | undefined

export function database(): Promise<Database> {
  return (cached ??= env().LF_MODE === "mock" ? db.local({ migrationsFolder: join(process.cwd(), "db", "migrations") }) : Promise.resolve(db(required("DATABASE_URL"))))
}

// launch-factory: 환경 읽기. 이름만 다루고 값은 어디에도 남기지 않는다.
// LF_MODE 는 항상 필수다 — 없으면 켜지지 않는다(조용히 mock 으로 가지 않는다). live 에서는 공급자 키가 모두 필수다.
import { loadAppEnv, type AppEnv } from "@launch-factory/env"

let cached: AppEnv | undefined

/** 처음 부를 때 한 번 검사한다. 빠진 이름은 모두 모아 한 번에 알린다(값은 싣지 않는다). */
export function env(): AppEnv {
  return (cached ??= loadAppEnv())
}

/** 설정값·비밀값 하나를 읽는다. 없으면 이름만 담아 던진다. */
export function required(name: string): string {
  const value = (env() as Record<string, string | undefined>)[name] ?? process.env[name]
  if (!value) throw new Error(`${name} is not set (see .env.example)`)
  return value
}

/** 없어도 되는 설정값. */
export function optional(name: string): string | undefined {
  return process.env[name] || undefined
}

// launch-factory: 제품마다 고치는 값. 이 파일은 제품 것이다 — 레지스트리를 다시 받으면 덮어쓸지 묻는다.
import type { Locale } from "@launch-factory/email"
import { env, required } from "@/lib/launch/env"

export const PRODUCT_NAME = "My Product"
/** 사용자 칸(user.locale)이 비었을 때 메일·오류 문구의 언어 */
export const DEFAULT_LOCALE: Locale = "en"
/** 가입 때 동의 기록에 남길 약관·개인정보 처리방침의 판. 문서를 고치면 올린다 */
export const CONSENT_VERSIONS = { terms: "2026-09-30", privacy: "2026-09-30" }
/** 결제 메일이 가리키는 화면 경로 */
export const ROUTES = { billing: "/account/billing", acceptPriceChange: "/account/billing/price-change", decline: "/account/billing/cancel", security: "/forgot-password", contact: "/contact" }

/** 앱 주소. mock 에서는 로컬 주소로 켜지고, live 에서는 NEXT_PUBLIC_APP_URL 이 필수다 */
export function appUrl(): string {
  // 빈 문자열은 없는 것으로 본다 — shadcn CLI 가 envVars 이름을 `NAME=`(빈 값)으로 .env.local 에 적는다
  return process.env.NEXT_PUBLIC_APP_URL || (env().LF_MODE === "mock" ? "http://localhost:3000" : required("NEXT_PUBLIC_APP_URL"))
}

// launch-factory: 광고성 메일 보내기와 2년 재확인(LFMAIL — G03·G07·A16). 광고성 메일은 **이 파일의 sendMarketingEmail 로만** 보낸다:
//   ① 동의·재확인·야간 점검(canSendMarketing) ② 받는 사람 전용 로그인 없는 수신거부 링크(서명 토큰) ③ 법정 표시·수신거부 헤더는 메일러가 단다(제목 「(광고)」·사업자 표시·한·영 안내·List-Unsubscribe).
// 한국법 근거와 이 구현이 따르는 규칙은 docs/qa/ux-audit/legal-basis.md §1 의 「G03·D07」「A05」「A06(추가)」다.
// 야간 점검은 기본으로 켠다(LF_MARKETING_NIGHT_GUARD=off 로 끈다) — 전자우편은 야간 동의 대상이 아니라서(시행령 제61조제2항) 법이 요구하는 점검은 아니다.
import { isPlaceholderEmail } from "@launch-factory/auth"
import { canSendMarketing, marketingLinks, runMarketingReconfirm, type MarketingSendDecision, type ReconfirmRunResult } from "@launch-factory/consent"
import { user } from "@launch-factory/db"
import { consentEmails, type MarketingAnnouncementInput } from "@launch-factory/email"
import { eq } from "drizzle-orm"
import { appUrl, DEFAULT_LOCALE, PRODUCT_NAME } from "@/lib/launch/config"
import { database } from "@/lib/launch/db"
import { linkSecret } from "@/lib/launch/link-secret"
import { mailer } from "@/lib/launch/mailer"

const nightGuardOn = () => process.env.LF_MARKETING_NIGHT_GUARD?.toLowerCase() !== "off"

/** 메일 한 통의 내용(받는 사람·언어·전송자는 이 파일이 채운다) */
export type MarketingContent = Pick<MarketingAnnouncementInput, "subject" | "heading" | "paragraphs"> & Partial<Pick<MarketingAnnouncementInput, "preview" | "cta">>

export type MarketingSendResult = { sent: true; id: string } | { sent: false; reason: Exclude<MarketingSendDecision, { ok: true }>["reason"] | "no_user" | "no_email" | "send_failed"; retryAt?: Date }

/**
 * 광고성 메일 한 통을 한 사람에게. 보내면 { sent: true }, 보내지 않으면 이유를 돌려준다(night 면 다시 시도할 시각 retryAt — 호출하는 쪽이 그때 다시 부른다).
 * 사업자 정보(LF_BUSINESS_*)가 비어 있으면 던진다(MarketingComplianceError) — 법정 표시 없는 광고 메일은 만들어지지 않는다.
 */
export async function sendMarketingEmail(userId: string, content: MarketingContent, o: { now?: Date } = {}): Promise<MarketingSendResult> {
  const db = await database()
  const [u] = await db.select({ email: user.email, name: user.name, locale: user.locale, timeZone: user.timeZone }).from(user).where(eq(user.id, userId)).limit(1)
  if (!u) return { sent: false, reason: "no_user" }
  if (isPlaceholderEmail(u.email)) return { sent: false, reason: "no_email" }
  const decision = await canSendMarketing(db, userId, { channel: "email", nightGuard: nightGuardOn(), ...(o.now ? { now: o.now } : {}) })
  if (!decision.ok) return decision.reason === "night" ? { sent: false, reason: "night", retryAt: decision.retryAt } : { sent: false, reason: decision.reason }
  const { unsubscribeUrl } = marketingLinks({ baseUrl: appUrl(), secret: linkSecret(), userId })
  const r = await mailer().send({
    to: u.email,
    template: "marketingAnnouncement",
    unsubscribeUrl,
    input: {
      ...content,
      locale: u.locale === "ko" || u.locale === "en" ? u.locale : DEFAULT_LOCALE,
      productName: PRODUCT_NAME,
      ...(u.name ? { recipientName: u.name } : {}),
      ...(u.timeZone ? { timeZone: u.timeZone } : {}),
    },
  })
  return r.ok ? { sent: true, id: r.id } : { sent: false, reason: "send_failed" }
}

/**
 * 2년 재확인 작업(A16, /api/cron/consents 가 하루 한 번 부른다). 동의한 지 2년이 지난 이메일 수신자에게 재확인 메일(전송자 명칭·동의 사실과 날짜·계속 받기/수신거부 링크)을 한 통씩 보낸다.
 * 두 번 돌아도 안전하고, 실패한 사람은 다음 실행이 이어서 한다. 이메일이 없는 대체 주소 계정은 기록만 남기고 넘어간다.
 */
export async function runReconfirm(): Promise<ReconfirmRunResult> {
  const emails = consentEmails(mailer(), { productName: PRODUCT_NAME, defaultLocale: DEFAULT_LOCALE })
  return runMarketingReconfirm({
    db: await database(),
    skip: (c) => isPlaceholderEmail(c.email),
    send: (c) => {
      const links = marketingLinks({ baseUrl: appUrl(), secret: linkSecret(), userId: c.userId })
      return emails.marketingReconfirm(c.email, { consentAt: c.consentAt, ...links, idempotencyKey: c.idempotencyKey }, { name: c.name, locale: c.locale, timeZone: c.timeZone })
    },
  })
}

// launch-factory: 광고 메일의 로그인 없는 수신거부(G03 — 정보통신망법 제50조·시행령 별표 6 공통 2: 수신거부는 전송에 쓴 연락처 외 정보를 요구하지 않는다 = 로그인 요구 금지).
// 주소의 `?t=` 는 서명 토큰(@launch-factory/consent 의 unsubscribeToken)이다. 이 주소가 메일 본문의 수신거부 링크이자 헤더 List-Unsubscribe 의 주소다(RFC 8058).
//   GET  — 본문 링크를 열면 그 자리에서 바로 철회하고 /email?r=… 결과 화면으로 보낸다. 메일 보안 프로그램이 미리 열어도 같은 결과다(이미 철회돼 있으면 아무것도 쓰지 않는다).
//   POST — Gmail·Yahoo 의 「한 번에 수신거부」(List-Unsubscribe-Post: List-Unsubscribe=One-Click). 쿠키·로그인 없이 같은 처리, 200/400 JSON.
// 철회가 실제로 일어났으면 처리 결과 통지 메일(정보통신망법 제50조제7항)을 응답 뒤에 보낸다(A06 과 같은 메일).
import { after } from "next/server"
import { withdrawByToken } from "@launch-factory/consent"
import { DEFAULT_LOCALE } from "@/lib/launch/config"
import { sendResultNotice } from "@/lib/launch/consents"
import { database } from "@/lib/launch/db"
import { linkSecret } from "@/lib/launch/link-secret"

export const runtime = "nodejs"
export const dynamic = "force-dynamic"

async function withdraw(token: string | null) {
  const result = await withdrawByToken(await database(), token, { secret: linkSecret() })
  if (result.ok && result.changed) {
    after(() => sendResultNotice({ userId: result.userId, changes: [{ channel: result.channel, granted: false }], at: result.at, locale: DEFAULT_LOCALE }, "unsubscribe_link").catch((e) => console.error("[unsubscribe] result notice failed", e)))
  }
  return result
}

const redirect = (to: string) => new Response(null, { status: 303, headers: { location: to, "cache-control": "no-store" } })

export async function GET(request: Request) {
  const result = await withdraw(new URL(request.url).searchParams.get("t"))
  return redirect(`/email?r=${result.ok ? "unsubscribed" : "invalid"}`)
}

export async function POST(request: Request) {
  const result = await withdraw(new URL(request.url).searchParams.get("t"))
  return Response.json({ ok: result.ok }, { status: result.ok ? 200 : 400, headers: { "cache-control": "no-store" } })
}

// launch-factory: 2년 재확인 메일의 「계속 받기」(A16). 주소의 `?t=` 는 기한이 있는 서명 토큰(keepToken)이다.
//   GET  — 링크를 열면 아무것도 바꾸지 않고 /email?a=keep&t=… 확인 화면으로 보낸다. 메일 보안 프로그램이 링크를 미리 열어도 동의가 갱신되지 않게 — 갱신은 사람이 확인 단추(POST)를 눌러야 한다.
//   POST — 확인 단추. 지금 동의 상태인 사람의 동의 시각을 지금으로 갱신하고(새 2년) /email?r=… 결과로 보낸다. 이미 철회한 사람은 되살리지 않는다.
import { keepByToken } from "@launch-factory/consent"
import { database } from "@/lib/launch/db"
import { linkSecret } from "@/lib/launch/link-secret"

export const runtime = "nodejs"
export const dynamic = "force-dynamic"

const redirect = (to: string) => new Response(null, { status: 303, headers: { location: to, "cache-control": "no-store" } })

export async function GET(request: Request) {
  const t = new URL(request.url).searchParams.get("t")
  return redirect(t ? `/email?a=keep&t=${encodeURIComponent(t)}` : "/email?r=invalid")
}

export async function POST(request: Request) {
  const fromQuery = new URL(request.url).searchParams.get("t")
  const form = fromQuery ? null : await request.formData().catch(() => null)
  const t = fromQuery ?? (typeof form?.get("t") === "string" ? (form?.get("t") as string) : null)
  const result = await keepByToken(await database(), t, { secret: linkSecret() })
  return redirect(`/email?r=${result.ok ? "kept" : result.reason === "withdrawn" ? "withdrawn" : "invalid"}`)
}

// launch-factory: 마케팅 수신동의 2년 재확인 Cron(하루 한 번 권장 — A16, 정보통신망법 제50조제8항 · 시행령 제62조의3).
// vercel.json 에 `{ "crons": [{ "path": "/api/cron/consents", "schedule": "20 5 * * *" }] }` 를 더한다. CRON_SECRET 이 없으면 401 이다.
// 두 번 와도 안전하다(보낸 기록이 있는 동의는 다시 뽑히지 않는다). 실패한 사람은 다음 실행이 이어서 한다. 응답은 { due, sent, skipped, failed } 건수다.
import { cronAuthorized, unauthorized } from "@/lib/launch/cron"
import { runReconfirm } from "@/lib/launch/marketing"

export const runtime = "nodejs"
export const dynamic = "force-dynamic"

export async function GET(request: Request) {
  if (!cronAuthorized(request)) return unauthorized()
  return Response.json(await runReconfirm())
}

// launch-factory: 로그인 없이 누르는 메일 링크(수신거부 · 계속 받기 · 가입 안 했어요)의 서명 비밀.
// 앱 비밀(BETTER_AUTH_SECRET)에서 용도를 섞어 파생한 값이라 세션 서명과 섞이지 않는다(HMAC 입력이 다르다). 새 환경 변수를 만들지 않는다.
// live 는 BETTER_AUTH_SECRET(32자 이상)이 필수다. mock 에서 없으면 프로세스마다 새로 만든다 — 재시작하면 그 전에 만든 링크는 열리지 않는다(개발 중에만 그렇다).
import { createHmac, randomBytes } from "node:crypto"
import { env, required } from "@/lib/launch/env"

let mockBase: string | undefined

export function linkSecret(): string {
  const e = env()
  const base = e.LF_MODE === "live" ? required("BETTER_AUTH_SECRET") : (e.BETTER_AUTH_SECRET ?? (mockBase ??= randomBytes(32).toString("hex")))
  return createHmac("sha256", base).update("lf-mail-links-v1").digest("hex")
}

// launch-factory: Cron 경로 인증. Vercel Cron 은 CRON_SECRET 이 있으면 `Authorization: Bearer <값>` 을 붙여 부른다
// (https://vercel.com/docs/cron-jobs/manage-cron-jobs#securing-cron-jobs). 값이 없거나 다르면 거절한다 — 비밀이 없으면 열어 두지 않는다.
import { timingSafeEqual } from "node:crypto"

export function cronAuthorized(request: Request): boolean {
  const secret = process.env.CRON_SECRET
  if (!secret) return false
  const given = request.headers.get("authorization") ?? ""
  const want = `Bearer ${secret}`
  return given.length === want.length && timingSafeEqual(Buffer.from(given), Buffer.from(want))
}

export const unauthorized = () => Response.json({ error: "unauthorized" }, { status: 401 })
